// src/slotActionFeedback.ts
class SlotActionFeedbackCoordinator {
  pending = new Map;
  activeKeys = new Set;
  submit(submission) {
    if (this.activeKeys.has(submission.key))
      return false;
    this.activeKeys.add(submission.key);
    this.pending.set(submission.submissionId, submission);
    submission.setDisabled(true);
    submission.showPopupError("");
    try {
      submission.dispatch();
      return true;
    } catch (error) {
      this.pending.delete(submission.submissionId);
      this.activeKeys.delete(submission.key);
      submission.setDisabled(false);
      submission.restorePending?.();
      submission.showPopupError(error instanceof Error ? error.message : String(error));
      return false;
    }
  }
  handle(feedback) {
    const submission = this.pending.get(feedback.submissionId);
    if (!submission || submission.key !== feedback.key || submission.action !== feedback.action)
      return false;
    if (feedback.status === "accepted") {
      submission.setBusy(feedback.key, feedback.statusText || submission.statusText, feedback.intent ?? submission.intent);
      submission.closePopup();
      return true;
    }
    this.pending.delete(feedback.submissionId);
    this.activeKeys.delete(feedback.key);
    if (feedback.status === "rejected") {
      submission.setDisabled(false);
      submission.restorePending?.();
      submission.showPopupError(feedback.message || "Relay could not accept this action. Please retry.");
      return true;
    }
    submission.finishBusy(feedback.key, feedback.status, feedback.message);
    return true;
  }
  clear() {
    this.pending.clear();
    this.activeKeys.clear();
  }
}

// src/mediaDomStability.ts
function observeRelayMediaMounts(root, onMount) {
  const observers = new Map;
  const scan = (node) => {
    if (!observers.has(node)) {
      const observer = new MutationObserver((mutations) => {
        const hostChanged = mutations.some((mutation) => {
          const target = mutation.target instanceof Element ? mutation.target : mutation.target.parentElement;
          return !target?.closest(".rrl-card, .dg-router-panel, .dg-relay-orb");
        });
        if (!hostChanged)
          return;
        for (const [observed, current] of observers) {
          if (observed instanceof ShadowRoot && !observed.host.isConnected) {
            current.disconnect();
            observers.delete(observed);
          }
        }
        scan(root);
        onMount();
      });
      observer.observe(node, { childList: true, subtree: true });
      observers.set(node, observer);
    }
    for (const element of Array.from(node.querySelectorAll("*"))) {
      if (element.shadowRoot)
        scan(element.shadowRoot);
    }
  };
  scan(root);
  return () => {
    for (const observer of observers.values())
      observer.disconnect();
    observers.clear();
  };
}
function setMediaText(element, text) {
  if (element && element.textContent !== text)
    element.textContent = text;
}

// src/runtimeLifecycle.ts
var empty = () => ({ setupCount: 0, disposeCount: 0, activeInstances: 0, lastSetupAt: 0, listeners: 0, observers: 0, timers: 0, subscriptions: 0, previewListeners: 0, abortControllers: 0, orbControllers: 0, settingsSubscriptions: 0, slotSubscriptions: 0, activeViews: 0, activeView: "", actionScopes: 0 });

class RelayRuntimeLifecycle {
  health;
  cleanups = [];
  previews = new Set;
  actions = new Set;
  disposed = false;
  constructor(previous) {
    this.health = { ...empty(), ...previous || {} };
    this.health.setupCount += 1;
    this.health.activeInstances = 1;
    this.health.lastSetupAt = Date.now();
    for (const key of ["listeners", "observers", "timers", "subscriptions", "previewListeners", "abortControllers", "orbControllers", "settingsSubscriptions", "slotSubscriptions", "activeViews", "actionScopes"])
      this.health[key] = 0;
    this.health.activeView = "";
  }
  track(cleanup, category = "subscription") {
    const counters = category === "listener" ? ["listeners"] : category === "observer" ? ["observers"] : category === "timer" ? ["timers"] : category === "settings" ? ["subscriptions", "settingsSubscriptions"] : category === "slot" ? ["subscriptions", "slotSubscriptions"] : ["subscriptions"];
    for (const key of counters)
      this.health[key] += 1;
    let active = true;
    const wrapped = () => {
      if (!active)
        return;
      active = false;
      try {
        cleanup();
      } finally {
        for (const key of counters)
          this.health[key] = Math.max(0, this.health[key] - 1);
      }
    };
    this.cleanups.push(wrapped);
    return wrapped;
  }
  activateView(view) {
    this.health.activeView = view;
    this.health.activeViews = view ? 1 : 0;
  }
  setOrbMounted(mounted) {
    this.health.orbControllers = mounted ? 1 : 0;
  }
  beginPreview(id) {
    this.previews.add(id);
    this.health.previewListeners = this.previews.size;
  }
  endPreview(id) {
    this.previews.delete(id);
    this.health.previewListeners = this.previews.size;
  }
  beginAction(id) {
    if (this.actions.has(id))
      return false;
    this.actions.add(id);
    this.health.actionScopes = this.actions.size;
    return true;
  }
  endAction(id) {
    this.actions.delete(id);
    this.health.actionScopes = this.actions.size;
  }
  createAbortController() {
    const controller = new AbortController;
    this.health.abortControllers += 1;
    controller.signal.addEventListener("abort", () => {
      this.health.abortControllers = Math.max(0, this.health.abortControllers - 1);
    }, { once: true });
    this.track(() => {
      if (!controller.signal.aborted)
        controller.abort();
    });
    return controller;
  }
  snapshot() {
    return { ...this.health };
  }
  dispose() {
    if (this.disposed)
      return;
    this.disposed = true;
    for (const cleanup of this.cleanups.splice(0).reverse())
      cleanup();
    this.previews.clear();
    this.actions.clear();
    Object.assign(this.health, { activeInstances: 0, activeViews: 0, activeView: "", previewListeners: 0, abortControllers: 0, orbControllers: 0, actionScopes: 0 });
    this.health.disposeCount += 1;
    this.health.lastDisposeAt = Date.now();
  }
}

// src/slotLifecycle.ts
var lifecycle = (generationActive, placementActive, terminal, canAbort = generationActive) => ({
  generationActive,
  placementActive,
  terminal,
  canAbort,
  blocksRegeneration: generationActive || placementActive
});
var SLOT_LIFECYCLE = {
  "recovered-pending": lifecycle(false, false, false),
  preparing: lifecycle(true, false, false),
  queued: lifecycle(true, false, false),
  parsing: lifecycle(true, false, false),
  generating: lifecycle(true, false, false),
  previewing: lifecycle(true, false, false),
  "placement-pending": lifecycle(false, true, false, false),
  "placement-repair-needed": lifecycle(false, false, false),
  completed: lifecycle(false, false, true),
  "image-unavailable": lifecycle(false, false, true),
  failed: lifecycle(false, false, true),
  cancelled: lifecycle(false, false, true)
};
function isGenerationActiveStatus(status) {
  return SLOT_LIFECYCLE[status].generationActive;
}
function isSlotLifecycleActive(status) {
  const semantics = SLOT_LIFECYCLE[status];
  return semantics.generationActive || semantics.placementActive;
}
function canAbortSlotStatus(status) {
  return SLOT_LIFECYCLE[status].canAbort;
}

