  function matchesAllReverieImageFilters(asset) {
    if (allChatsChatFilter !== "all" && asset.chatId !== allChatsChatFilter)
      return false;
    if (allChatsCharacterFilter !== "all" && !(asset.characterNames || []).includes(allChatsCharacterFilter))
      return false;
    if (allChatsTargetFilter !== "all" && String(asset.target) !== allChatsTargetFilter)
      return false;
    const surface = String((asset.metadata || {}).surfaceId || asset.targetApp || "unknown");
    if (allChatsSurfaceFilter !== "all" && surface !== allChatsSurfaceFilter)
      return false;
    if (allChatsStatusFilter === "available" && (!asset.imageUrl || asset.status === "unavailable"))
      return false;
    if (allChatsStatusFilter === "unavailable" && asset.status !== "unavailable")
      return false;
    if (allChatsStatusFilter === "retained" && !asset.sourceDeletedAt)
      return false;
    const age = Date.now() - asset.createdAt;
    if (allChatsDateFilter === "7d" && age > 7 * 86400000)
      return false;
    if (allChatsDateFilter === "30d" && age > 30 * 86400000)
      return false;
    if (allChatsDateFilter === "90d" && age > 90 * 86400000)
      return false;
    const query = allChatsQuery.trim().toLocaleLowerCase();
    if (!query)
      return true;
    return JSON.stringify({ chat: asset.chatId, characters: asset.characterNames, target: asset.target, surface, caption: asset.caption, scene: asset.originalSceneBrief, prompt: asset.resolvedPositivePrompt, metadata: asset.metadata }).toLocaleLowerCase().includes(query);
  }
