  function renderSlotVersionHistory() {
    const box = document.createElement("div");
    box.appendChild(renderAssetLibrary());
    box.appendChild(renderSlotFilters(historyFilter, (value) => {
      historyFilter = value;
      renderPanel();
    }));
    const items = [];
    for (const record of records) {
      if (!matchesSlotFilter(record, historyFilter))
        continue;
      if (record.status === "completed" && record.imageUrl)
        items.push({ record, version: record, timestamp: record.completedAt || record.updatedAt });
      else if (record.recoverySource && (record.status === "completed" || record.status === "failed"))
        items.push({ record, version: record, timestamp: record.completedAt || record.failedAt || record.updatedAt });
      record.history.forEach((version, historyIndex) => items.push({ record, version, historyIndex, timestamp: version.generatedAt }));
    }
    items.sort((a, b) => b.timestamp - a.timestamp);
    const historyTitle = document.createElement("h3");
    historyTitle.className = "dg-section-title";
    historyTitle.textContent = "Slot Version History";
    box.appendChild(historyTitle);
    if (items.length === 0) {
      box.appendChild(empty2(historyFilter === "all" ? "No slot history yet." : `No ${filterLabel(historyFilter).toLocaleLowerCase()} history entries.`));
      return box;
    }
    const groups = new Map;
    for (const item of items) {
      const label = historyDateLabel(item.timestamp);
      const list = groups.get(label) || [];
      list.push(item);
      groups.set(label, list);
    }
    for (const [label, list] of groups) {
      const group = document.createElement("section");
      group.className = "dg-history-group";
      const heading = document.createElement("h3");
      heading.className = "dg-history-date";
      heading.textContent = label;
      const track = document.createElement("div");
      track.className = "dg-history-track";
      for (const item of list)
        track.appendChild(renderHistoryTimelineItem(item.record, item.version, item.historyIndex, item.timestamp));
      group.append(heading, track);
      box.appendChild(group);
    }
    return box;
  }
  function renderHistoryTimelineItem(record, version, historyIndex, timestamp) {
    const item = document.createElement("div");
    item.className = "dg-history-item";
    const image2 = version.imageUrl ? document.createElement("img") : document.createElement("div");
    image2.className = version.imageUrl ? "dg-history-thumb" : "dg-history-thumb dg-thumb-empty";
    if (image2 instanceof HTMLImageElement) {
      image2.src = version.imageUrl || "";
      image2.alt = record.alt || record.slot;
    } else
      image2.textContent = record.status === "failed" ? "Recovered error" : "Image unavailable";
    image2.title = version.imageUrl ? "Open image" : "Image unavailable";
    image2.addEventListener("click", () => {
      if (historyIndex === undefined)
        openLightbox(record);
      else
        openHistoryVersionImage(record, version, historyIndex);
    });
    const main = document.createElement("div");
    const head = document.createElement("div");
    head.className = "dg-history-head";
    const identity = document.createElement("div");
    const title = document.createElement("div");
    title.className = "dg-history-title";
    title.textContent = `${appLabel(record)} / ${slotLabel(record)}`;
    const attempt = version.attemptNumber || record.attemptNumber || 0;
    const duration = record.attempts?.find((entry) => entry.attemptNumber === attempt)?.durationMs;
    const meta = document.createElement("div");
    meta.className = "dg-slot-meta";
    const provider = version.imageProvider || record.imageProvider || (record.recoverySource ? "Provider unavailable" : "Unknown provider");
    const model = version.imageModel || record.imageModel || (record.recoverySource ? "Model unavailable" : "Unknown model");
    meta.textContent = `${new Date(timestamp).toLocaleTimeString()}${duration !== undefined ? ` / ${(duration / 1000).toFixed(1)}s` : ""}
${record.requestId} / ${provider} / ${model}${record.recoveredFromInactiveSwipe ? " / Inactive swipe" : ""}`;
    identity.append(title, meta);
    const modeKnown = version.highResMode !== undefined || record.highResMode !== undefined;
    head.append(identity, chip(modeKnown ? version.highResMode ?? record.highResMode ? "High-Res" : "Normal" : "Mode unknown", version.highResMode ? "completed" : ""));
    const prompt = document.createElement("div");
    prompt.className = "dg-history-prompt";
    prompt.textContent = version.resolvedPositivePrompt || record.originalSceneBrief || recoveryHistoryMessage(record);
    const actions = document.createElement("div");
    actions.className = "dg-actions";
    if (historyIndex === undefined)
      actions.appendChild(button("Open", () => openLightbox(record), !record.imageUrl, "standard"));
    else
      actions.appendChild(button("Restore", () => ctx.sendToBackend({ type: "restore_history", chatId: record.chatId, key: record.key, historyIndex }), false, "primary"));
    actions.appendChild(button("Metadata", () => openMetadata(record, historyIndex === undefined ? undefined : version, historyIndex)));
    main.append(head, prompt, actions);
    item.append(image2, main);
    return item;
  }
  function historyDateLabel(timestamp) {
    const date = new Date(timestamp);
    const today = new Date;
    today.setHours(0, 0, 0, 0);
    const day = new Date(date);
    day.setHours(0, 0, 0, 0);
    const difference = Math.round((today.getTime() - day.getTime()) / 86400000);
    if (difference === 0)
      return "Today";
    if (difference === 1)
      return "Yesterday";
    return date.toLocaleDateString(undefined, { year: "numeric", month: "long", day: "numeric" });
  }
