  function redactSecrets(value, key = "") {
    const sensitive = /api[_-]?key|token|secret|authorization|password|cookie|session|credential/i;
    if (sensitive.test(key))
      return "[REDACTED]";
    if (Array.isArray(value))
      return value.map((item) => redactSecrets(item));
    if (value && typeof value === "object") {
      return Object.fromEntries(Object.entries(value).map(([entryKey, entryValue]) => [entryKey, redactSecrets(entryValue, entryKey)]));
    }
    return value;
  }
