  function helpTip(labelText, helpText = "") {
    const wrap = document.createElement("span");
    wrap.className = "dg-help";
    const trigger = document.createElement("span");
    trigger.className = "dg-help-trigger";
    trigger.setAttribute("role", "button");
    trigger.tabIndex = 0;
    trigger.setAttribute("aria-label", `Help for ${labelText}`);
    trigger.setAttribute("aria-expanded", "false");
    const tooltipId = `dg-help-${Math.random().toString(36).slice(2, 10)}`;
    trigger.setAttribute("aria-describedby", tooltipId);
    trigger.textContent = "?";
    const popover = document.createElement("span");
    popover.className = "dg-help-popover";
    popover.id = tooltipId;
    popover.setAttribute("role", "tooltip");
    popover.textContent = settingHelp(labelText, helpText);
    let portal = null;
    let pinned = false;
    let closeTimer = null;
    const onDocumentPointerDown = (event) => {
      const target = event.target;
      if (target && (trigger.contains(target) || popover.contains(target)))
        return;
      pinned = false;
      close();
    };
    const position = () => {
      if (!portal)
        return;
      const triggerRect = trigger.getBoundingClientRect();
      const width = Math.max(180, Math.min(280, window.innerWidth - 24));
      popover.style.width = `${width}px`;
      popover.style.left = "12px";
      popover.style.top = "12px";
      const measured = popover.getBoundingClientRect();
      const left = Math.max(12, Math.min(window.innerWidth - width - 12, triggerRect.left + triggerRect.width / 2 - width / 2));
      const above = triggerRect.top - measured.height - 8;
      const top = above >= 12 ? above : Math.min(window.innerHeight - measured.height - 12, triggerRect.bottom + 8);
      popover.style.left = `${left}px`;
      popover.style.top = `${Math.max(12, top)}px`;
    };
    const close = () => {
      if (closeTimer !== null) {
        window.clearTimeout(closeTimer);
        closeTimer = null;
      }
      wrap.classList.remove("is-open");
      popover.classList.remove("is-open");
      trigger.setAttribute("aria-expanded", "false");
      window.removeEventListener("resize", position);
      document.removeEventListener("scroll", position, true);
      document.removeEventListener("pointerdown", onDocumentPointerDown, true);
      if (portal) {
        wrap.appendChild(popover);
        portal.remove();
        portal = null;
      }
      popover.removeAttribute("style");
      if (closeActiveHelpPopover === close)
        closeActiveHelpPopover = null;
    };
    const open = () => {
      if (closeTimer !== null) {
        window.clearTimeout(closeTimer);
        closeTimer = null;
      }
      if (portal) {
        position();
        return;
      }
      closeActiveHelpPopover?.();
      portal = document.createElement("span");
      portal.className = "dg-router-panel dg-help-portal";
      portal.appendChild(popover);
      document.body.appendChild(portal);
      wrap.classList.add("is-open");
      popover.classList.add("is-open");
      trigger.setAttribute("aria-expanded", "true");
      closeActiveHelpPopover = close;
      position();
      window.addEventListener("resize", position);
      document.addEventListener("scroll", position, true);
      document.addEventListener("pointerdown", onDocumentPointerDown, true);
    };
    const scheduleClose = () => {
      if (pinned)
        return;
      if (closeTimer !== null)
        window.clearTimeout(closeTimer);
      closeTimer = window.setTimeout(close, 120);
    };
    const toggle = (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (portal && pinned) {
        pinned = false;
        close();
      } else {
        pinned = true;
        open();
      }
    };
    trigger.addEventListener("click", toggle);
    trigger.addEventListener("pointerenter", open);
    trigger.addEventListener("pointerleave", scheduleClose);
    trigger.addEventListener("focus", open);
    trigger.addEventListener("blur", scheduleClose);
    popover.addEventListener("pointerenter", () => {
      if (closeTimer !== null) {
        window.clearTimeout(closeTimer);
        closeTimer = null;
      }
    });
    popover.addEventListener("pointerleave", scheduleClose);
    trigger.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ")
        toggle(event);
      else if (event.key === "Escape") {
        pinned = false;
        close();
        trigger.blur();
      }
    });
    wrap.append(trigger, popover);
    return wrap;
  }
